import http from "./httpClient.js";
import initApp from "../utils/initApp.js";
import { useDashboardStore } from "@/store/dashboardStore.js";

class DashboardApi {
  API = {
    PERSON:
      "/resources/modeler/pno/person?current=true&select=preferredcredentials&select=collabspaces",
    FEDERATED_SEARCH: "/federated/search",
  };

  getCollabspaces() {
    return http.get(this.API.PERSON);
  }

  fetchDashboardData(type) {
    return http.post(this.API.FEDERATED_SEARCH, this.buildPayload(type));
  }

  fetchFilteredDashboardData(type, facetRefines = []) {
    const refine = Object.assign(
      {},
      ...facetRefines.map(({ key, value, valueTo }) =>
        valueTo
          ? this.dateRangeRefineOf(key, value, valueTo)
          : this.refineOf(key, value),
      ),
    );

    return http.post(
      this.API.FEDERATED_SEARCH,
      this.buildPayload(type, refine),
    );
  }

  fetchFacetDrilldown(
    type,
    facetKey,
    facetValue,
    pageSize = 10,
    nextStart = null,
    extraFacetRefines = [],
  ) {
    const cfg = this.getTypeCfg(type);
    const extraRefine = Object.assign(
      {},
      ...extraFacetRefines.map(({ key, value, valueTo }) =>
        valueTo
          ? this.dateRangeRefineOf(key, value, valueTo)
          : this.refineOf(key, value),
      ),
    );
    // Date facets ("ds6w:when/...") need a real date-range query clause —
    // the raw bucket value ("2026/04") can't be matched as an exact refine.
    if (facetKey && facetKey.startsWith("ds6w:when/")) {
      const predicate = facetKey.split("/").pop();
      const { from, to } = this.monthRangeUTC(facetValue);
      const query = `${cfg.query} AND [${predicate}]>="${from}" AND [${predicate}]<="${to}"`;
      return http.post(
        this.API.FEDERATED_SEARCH,
        this.buildPayload(type, extraRefine, pageSize, nextStart, query),
      );
    }
    return http.post(
      this.API.FEDERATED_SEARCH,
      this.buildPayload(
        type,
        { ...extraRefine, ...this.refineOf(facetKey, facetValue) },
        pageSize,
        nextStart,
      ),
    );
  }

  // "2026/04" -> UTC ISO bounds of that calendar month in IST (tenant timezone, UTC+5:30)
  monthRangeUTC(input) {
    let y, m;
    if (/^\d{4}[/-]\d{1,2}$/.test(input)) {
      const parts = input.split(/[/-]/);
      y = Number(parts[0]);
      m = Number(parts[1]);
    } else {
      // Handle month name formats
      const date = new Date("1 " + input);

      if (isNaN(date)) {
        throw new Error("Invalid date format: " + input);
      }

      y = date.getFullYear();
      m = date.getMonth() + 1;
    }

    const IST_MS = 5.5 * 60 * 60 * 1000;
    const from = new Date(
      Date.UTC(y, m - 1, 1, 0, 0, 0) - IST_MS,
    ).toISOString();
    const to = new Date(Date.UTC(y, m, 0, 23, 59, 59) - IST_MS).toISOString();
    return { from, to };
  }

  /* =========================
   * Helper Methods
   * ========================= */
  refineOf(key, value) {
    return {
      [key]: [
        {
          type: "string",
          object: value,
          disptext: value,
          field: ["implicit"],
        },
      ],
    };
  }

  dateRangeRefineOf(key, from, to) {
    return {
      [key]: [
        {
          type: "date",
          object: to ? { from, to } : { from },
          disptext: to ? `${from} to ${to}` : from,
          field: ["implicit"],
        },
      ],
    };
  }

  // Built from store.typeConfig (fetched from the backend at app start — see
  // main.js). Same shape as before: {query, refine}. If a custom form is set
  // (Custom Query / default dashboard), it is applied on top.
  getTypeCfg(type) {
    const store = useDashboardStore();
    const entry = store.getTypeConfig.find((t) => t.name === type);
    if (!entry) return { query: "(3dexpprd:#all)", refine: {} };
    const cfg = {
      query: entry.query,
      refine: entry.refineValue
        ? this.refineOf("ds6w:what/ds6w:type", entry.refineValue)
        : {},
    };
    return store.customForm ? this.applyForm(cfg, store.customForm) : cfg;
  }

  // Form values -> query clauses. Same [predicate] syntax the date drill-down
  // already uses, so it is known to work with federated search.
  applyForm(cfg, f) {
    // Default dashboard: project names found from Task/Issue -> plain-text query
    if (f.projectNames?.length)
      return {
        ...cfg,
        query: f.projectNames.map((n) => `"${n}"`).join(" OR "),
      };

    const IST = 5.5 * 3600 * 1000;
    const iso = (d, end) =>
      new Date(
        Date.parse(d + (end ? "T23:59:59Z" : "T00:00:00Z")) - IST,
      ).toISOString();
    const parts = [cfg.query];
    if (f.keyword?.trim()) parts.push(`(${f.keyword.trim()})`);
    const eq = (pred, val) =>
      val?.trim() && parts.push(`[${pred}]:"${val.trim()}"`);
    eq("ds6w:status", f.status);
    eq("ds6w:policy", f.policy);
    eq("ds6w:responsible", f.owner);
    eq("ds6w:lastModifiedBy", f.lastModifiedBy);
    eq("ds6w:originator", f.originator);
    eq("ds6w:project", f.project);
    const range = (pred, from, to) => {
      if (from) parts.push(`[${pred}]>="${iso(from)}"`);
      if (to) parts.push(`[${pred}]<="${iso(to, true)}"`);
    };
    range("ds6w:created", f.createdFrom, f.createdTo);
    range("ds6w:modified", f.modifiedFrom, f.modifiedTo);
    return { ...cfg, query: parts.join(" AND ") };
  }

  buildPayload(
    type,
    extraRefine = {},
    nresults = 10,
    nextStart,
    queryOverride,
  ) {
    const cfg = this.getTypeCfg(type);

    return {
      with_indexing_date: true,
      with_synthesis: true,
      with_nls: false,

      label: `3DSearch-Widget-${Date.now()}`,
      locale: "en",

      select_predicate: [
        "ds6w:label",
        "ds6w:type",
        "ds6w:description",
        "ds6w:identifier",
        "ds6w:modified",
        "ds6w:created",
        "ds6wg:revision",
        "ds6w:status",
        "ds6w:responsible",
        "owner",
        "ds6w:responsibleUid",
        "ds6wg:filesize",
        "ds6w:project",
        "ds6w:dataSource",
        "ds6w:community",
        "ds6w:originator",
        "dsgeo:referential",
        "ds6w:lastModifiedBy",
        "ds6w:repository",
        "dcterms:title",
        "dcterms:description",
      ],

      with_synthesis_hierarchical: true,

      select_file: ["icon", "thumbnail_2d"],

      query: queryOverride || cfg.query,

      refine: {
        ...cfg.refine,
        ...extraRefine,
      },

      select_exclude_synthesis: ["ds6w:what/ds6w:topic"],

      order_by: "desc",
      order_field: "relevance",

      select_snippets: [
        "ds6w:snippet",
        "ds6w:label:snippet",
        "ds6w:responsible:snippet",
        "ds6w:community:snippet",
        "swym:message_text:snippet",
      ],

      nresults,

      source: cfg.source || ["3dspace"],

      tenant: initApp.store().getServer,

      login: {
        "3dspace": {
          SecurityContext: initApp.getCTX(),
        },
      },

      ...(nextStart && {
        next_start: nextStart,
      }),
    };
  }

  /* =========================
   * Default dashboard: Projects by sub object
   * ========================= */
  fetchProjectNamesBySubObject(form) {
    return ["Task", "Phase", "Milestone"].includes(form.subType)
      ? this.fetchProjectNamesByTask(form)
      : this.fetchProjectNamesByIssue(form); // Issue, Risk, Route
  }

  // shared pager: runs payloadFn(start) for every page, calls onResult(r) per result
  async pageAll(payloadFn, onResult) {
    const seen = new Set();
    let next = null;
    for (let page = 0; page < 20; page++) {
      const json = await http.post(this.API.FEDERATED_SEARCH, payloadFn(next));
      const results = json.results || [];
      results.forEach(onResult);
      next = json.infos?.next_start;
      if (results.length < 40 || !next || seen.has(next)) break;
      seen.add(next);
    }
  }

  // ---------- TASK / PHASE / MILESTONE: usedInProject in the results ----------
  async fetchProjectNamesByTask({ subType = "Task", name, status }) {
    const KEY = "ds6w:where/ds6w:context/ds6w:usedInProject";
    const refine = {
      ...this.refineOf("ds6w:what/ds6w:type", subType),
      ...(status
        ? this.refineOf("ds6w:what/ds6w:status", `Project Task.${status}`)
        : {}),
    };
    const payloadFn = (start) => {
      const p = this.buildPayload("Task", refine, 40, start, name.trim());
      p.refine = refine; // don't inherit the Task type refine from config
      p.select_predicate = [...new Set([...p.select_predicate, KEY])];
      p.source = ["3dspace", "swym"];
      if (!start) p.start = "0";
      return p;
    };

    const names = new Set();
    await this.pageAll(payloadFn, (r) =>
      (r.attributes || [])
        .filter((a) => a.name === KEY)
        .forEach((a) => [].concat(a.value).forEach((v) => v && names.add(v))),
    );
    return [...names];
  }

  // ---------- ISSUE / RISK / ROUTE: resourceid -> getEcosystem -> project ----------
  async fetchProjectNamesByIssue({ subType = "Issue", name }) {
    // relation per type; only issue_to is confirmed -> verify Risk / Route
    const RELATIONS = {
      Issue: ["issue_to"],
      Risk: ["issue_to"],
      Route: ["issue_to"],
    };
    const payloadFn = (start) => {
      const p = this.buildPayload("Issue", {}, 40, start, name.trim());
      delete p.refine; // no refine for this flow
      p.select_predicate = [
        ...new Set([...p.select_predicate, "ds6w:containerUid", "resourceid"]),
      ];
      p.source = ["3dspace", "swym"];
      if (!start) p.start = "0";
      p.specific_source_parameter = {
        "3dspace": {
          additional_query:
            ' AND NOT (flattenedtaxonomies:("types/Person" OR "types/Security Context"))',
        },
      };
      return p;
    };

    const ids = new Set();
    await this.pageAll(payloadFn, (r) => {
      const rid = (r.attributes || []).find((a) => a.name === "resourceid")
        ?.value;
      const id = [].concat(rid || [])[0];
      if (id) ids.add(id);
    });
    console.log(subType, "ids", [...ids]);
    return ids.size
      ? this.fetchIssueProjects([...ids], RELATIONS[subType])
      : [];
  }

  async fetchIssueProjects(ids, relations = ["issue_to"]) {
    const store = useDashboardStore();
    const json = await http.post(
      `/resources/enorelnav/v2/navigate/getEcosystem?tenant=${store.getServer}`,
      {
        widgetId: "preview-d887ae",
        label: `ENORIPE_AP-admin_platform-${Date.now()}`,
        lang: "en",
        ids,
        trueREST: false,
        direction: "out",
        restrictedMode: false,
        responseMode: "ObjectsAndLinks",
        relations,
      },
      { headers: { SecurityContext: initApp.getCTX() } },
    );
    console.log("getEcosystem response", json);
    const list = json.objects || json.data || json.results || [];
    return list
      .filter((o) => !ids.includes(o.id || o.physicalid))
      .map((o) => o.title || o.label || o.name || o.displayName)
      .filter(Boolean);
  }
}

export default new DashboardApi();