<template>
  <v-dialog
    :model-value="modelValue"
    max-width="550"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <div class="sv-card">
      <div class="sv-head">
        <span class="title">
          {{ editView ? "Edit View" : "Save Current View" }}
        </span>

        <v-icon
          icon="mdi-close"
          size="22"
          class="close-icon"
          @click="close"
        />
      </div>

      <!-- View Name -->
      <div class="field">
        <label>View Name *</label>

        <v-text-field
          v-model="name"
          placeholder="Enter view name"
          variant="outlined"
          density="comfortable"
          hide-details
          maxlength="100"
        />
      </div>

      <!-- Type -->
      <div class="field">
        <label>Type</label>

        <v-text-field
          v-model="type"
          variant="outlined"
          density="comfortable"
          hide-details
          disabled
        />
      </div>

      <!-- Description -->
      <div class="field">
        <label>Description (optional)</label>

        <v-textarea
          v-model="desc"
          placeholder="Enter description"
          variant="outlined"
          density="comfortable"
          hide-details
          rows="3"
          maxlength="500"
        />
      </div>

      <div class="sv-actions">
        <button
          class="btn-outline"
          @click="close"
        >
          Cancel
        </button>

        <button
          class="btn-primary"
          :disabled="!name.trim()"
          @click="save"
        >
          {{ editView ? "Update" : "Save" }}
        </button>
      </div>
    </div>
  </v-dialog>
</template>

<script>
import { useDashboardStore } from "@/store/dashboardStore";

export default {
  name: "SaveViewDialog",
  setup() {
    return { store: useDashboardStore() };
  },
  props: {
    modelValue: Boolean,
    editView: Object,
  },

  emits: ["update:modelValue", "save"],

  data() {
    return {
      name: "",
      type: this.store.type,
      desc: "",
    };
  },

  watch: {
    modelValue(value) {
      if (!value) return;

      if (this.editView) {
        this.name = this.editView.name || "";
        this.type = this.editView.type || this.store.type;
        this.desc = this.editView.desc || "";
      } else {
        this.name = "";
        this.type = this.store.type;
        this.desc = "";
      }
    },
  },

  methods: {
    close() {
      this.$emit("update:modelValue", false);
    },

    save() {
      this.$emit("save", {
        name: this.name.trim(),
        type: this.type,
        desc: this.desc,
      });

      this.close();
    },
  },
};
</script>

<style scoped>
.sv-card {
  background: white;
  border-radius: 14px;
  padding: 24px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.18);
  animation: sv-pop 0.18s ease-out;
}
@media (max-width: 480px) {
  .sv-card { padding: 14px; }
  .sv-actions { flex-direction: column-reverse; }
  .sv-actions .btn-primary, .sv-actions .btn-outline { width: 100%; }
}

@keyframes sv-pop {
  from { opacity: 0; transform: scale(0.96) translateY(6px); }
  to { opacity: 1; transform: scale(1) translateY(0); }
}

.sv-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.title {
  font-size: 22px;
  font-weight: 700;
}

.close-icon {
  cursor: pointer;
  border-radius: 50%;
  padding: 4px;
  transition: background 0.15s ease;
}
.close-icon:hover {
  background: #f0f2f5;
}

.field {
  margin-bottom: 18px;
}

.field label {
  display: block;
  margin-bottom: 6px;
  font-size: 14px;
  color: #555;
  font-weight: 500;
}

.sv-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 26px;
}

.btn-outline {
  min-width: 90px;
  height: 42px;
  border: 1.5px solid #d8d8d8;
  border-radius: 8px;
  background: white;
  cursor: pointer;
  font-size: 14px;
  transition: background 0.15s ease, border-color 0.15s ease, transform 0.1s ease;
}
.btn-outline:hover {
  background: #f5f7fa;
  border-color: #bbb;
}
.btn-outline:active {
  transform: scale(0.97);
}

.btn-primary {
  min-width: 90px;
  height: 42px;
  border: none;
  border-radius: 8px;
  background: #0f62fe;
  color: white;
  cursor: pointer;
  font-weight: 600;
  font-size: 14px;
  transition: background 0.15s ease, box-shadow 0.15s ease, transform 0.1s ease;
}
.btn-primary:hover:not(:disabled) {
  background: #0b4fd1;
  box-shadow: 0 2px 8px rgba(15, 98, 254, 0.35);
}
.btn-primary:active:not(:disabled) {
  transform: scale(0.97);
}

.btn-primary:disabled {
  background: #bfbfbf;
  cursor: not-allowed;
}
</style>