      <div class="kpi-label">Total {{ type }}</div>
      <div class="kpi-value">{{ fmt(total) }}</div>
    </div>
    <div v-for="k in kpis" :key="k.label" class="kpi-card">
      <div class="kpi-label">{{ k.label }}</div>
      <div class="kpi-value-row">
        <v-icon :icon="k.icon" size="18" :style="{ color: k.color }" />
        <span class="kpi-value">{{ fmt(k.value) }}</span>
      </div>
      <div class="kpi-pct" :style="{ color: k.color }">{{ k.pct }}%</div>
    </div>
  </div>
</template>

<script>


export default {
